    12	public class CorporatePricingStrategy implements PricingStrategy {
    13	    private static final Map<String, Integer> COMPANY_DISCOUNTS = new HashMap<>();
    14	
    15	    static {
    16	        COMPANY_DISCOUNTS.put("TECNOSUL", 12);
    17	        COMPANY_DISCOUNTS.put("AGROVALE", 18);
    18	        COMPANY_DISCOUNTS.put("FARMAVIDA", 25);
    19	    }
    20	
    21	    @Override
    22	    public PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) throws ApiException {
    23	        if (companyCode == null || !COMPANY_DISCOUNTS.containsKey(companyCode)) {
    24	            throw new ApiException(400, "INVALID_REQUEST", "Invalid or missing company code for CORPORATE rate plan");
    25	        }
    26	
    27	        BigDecimal subtotal = BigDecimal.ZERO;
    28	        LocalDate current = checkIn;
    29	
    30	        while (current.isBefore(checkOut)) {
    31	            BigDecimal nightPrice = room.getNightlyRate();
    32	
    33	            if (DateHelper.isHighSeason(current)) {
    34	                nightPrice = MoneyRounder.multiply(nightPrice, BigDecimal.valueOf(1.2));
    35	            }
    36	
    37	            subtotal = MoneyRounder.add(subtotal, nightPrice);
    38	            current = current.plusDays(1);
    39	        }
    40	
    41	        int discountPercent = COMPANY_DISCOUNTS.get(companyCode);
    42	        BigDecimal discount = MoneyRounder.percentage(subtotal, discountPercent);
    43	        BigDecimal total = MoneyRounder.subtract(subtotal, discount);
    44	
    45	        return new PricingResult(subtotal, discount, total, BigDecimal.valueOf(100));
    46	    }
    47	}
