     7	import java.time.LocalDate;
     8	import java.util.HashMap;
     9	import java.util.Map;
    10	
    11	public class WeekendPackagePricingStrategy implements PricingStrategy {
    12	    private static final Map<String, BigDecimal> PACKAGE_PRICES = new HashMap<>();
    13	
    14	    static {
    15	        PACKAGE_PRICES.put("STANDARD", new BigDecimal("520.00"));
    16	        PACKAGE_PRICES.put("DELUXE", new BigDecimal("820.00"));
    17	        PACKAGE_PRICES.put("SUITE", new BigDecimal("1200.00"));
    18	    }
    19	
    20	    @Override
    21	    public PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) throws ApiException {
    22	        if (nights != 2) {
    23	            throw new ApiException(400, "INVALID_REQUEST", "Weekend package requires exactly 2 nights (Friday to Sunday)");
    24	        }
    25	
    26	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
    27	            throw new ApiException(400, "INVALID_REQUEST", "Weekend package check-in must be on Friday");
    28	        }
    29	
    30	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
    31	            throw new ApiException(400, "INVALID_REQUEST", "Weekend package check-out must be on Sunday");
    32	        }
    33	
    34	        BigDecimal price = PACKAGE_PRICES.get(room.getType());
    35	        if (price == null) {
    36	            throw new ApiException(400, "INVALID_REQUEST", "Weekend package not available for this room type");
    37	        }
    38	
    39	        BigDecimal discount = BigDecimal.ZERO;
    40	        BigDecimal total = price;
    41	
    42	        return new PricingResult(price, discount, total, new BigDecimal("50"));
    43	    }
    44	}
