     1	package com.pousada.service;
     2	
     3	import com.pousada.domain.*;
     4	import com.pousada.exception.ApiException;
     5	import com.pousada.service.pricing.PricingStrategy;
     6	import com.pousada.service.pricing.PricingStrategyFactory;
     7	import com.pousada.util.MoneyRounder;
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	import java.util.ArrayList;
    11	import java.util.List;
