    13	public class ReservationService {
    14	    private final List<Reservation> reservations = new ArrayList<>();
    15	    private final RoomService roomService;
    16	    private final MessageService messageService;
    17	    private long nextId = 1;
    18	
    19	    public ReservationService(RoomService roomService, MessageService messageService) {
    20	        this.roomService = roomService;
    21	        this.messageService = messageService;
    22	    }
    23	
    24	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    25	                                       String guestCpf, LocalDate checkIn, LocalDate checkOut,
    26	                                       int guests, RatePlan ratePlan, String companyCode) throws ApiException {
    27	        if (guests < 1) {
    28	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
    29	        }
    30	
    31	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    32	            throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
    33	        }
    34	
    35	        Room room = roomService.getRoomByNumber(roomNumber);
    36	
    37	        if (guests > room.getCapacity()) {
    38	            throw new ApiException(422, "CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
    39	        }
    40	
    41	        checkRoomAvailability(roomNumber, checkIn, checkOut);
    42	
    43	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    44	
    45	        PricingStrategy pricingStrategy = PricingStrategyFactory.getStrategy(ratePlan);
    46	        PricingStrategy.PricingResult pricingResult = pricingStrategy.calculatePrice(room, checkIn, checkOut, nights, companyCode);
    47	
    48	        Reservation reservation = new Reservation(
    49	                nextId++,
    50	                roomNumber,
    51	                guestName,
    52	                guestEmail,
    53	                guestCpf,
    54	                checkIn,
    55	                checkOut,
    56	                guests,
    57	                ratePlan,
    58	                companyCode,
    59	                nights,
    60	                pricingResult.subtotal,
    61	                pricingResult.discount,
    62	                pricingResult.total
    63	        );
    64	
    65	        reservations.add(reservation);
    66	        return reservation;
    67	    }
    68	
    69	    public Reservation getReservation(long id) throws ApiException {
    70	        return reservations.stream()
    71	                .filter(r -> r.getId() == id)
    72	                .findFirst()
    73	                .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
    74	    }
    75	
    76	    public Reservation confirmReservation(long id) throws ApiException {
    77	        Reservation reservation = getReservation(id);
    78	
    79	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    80	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only pending reservations can be confirmed");
    81	        }
    82	
    83	        reservation.setStatus(ReservationStatus.CONFIRMED);
    84	        reservation.setAmountPaid(reservation.getTotal());
    85	
    86	        sendConfirmationEmail(reservation);
    87	
    88	        return reservation;
    89	    }
    90	
    91	    public Reservation checkIn(long id) throws ApiException {
    92	        Reservation reservation = getReservation(id);
    93	
    94	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
    95	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only confirmed reservations can check in");
    96	        }
    97	
    98	        reservation.setStatus(ReservationStatus.CHECKED_IN);
    99	
   100	        return reservation;
   101	    }
   102	
   103	    public ReservationDocument checkOut(long id) throws ApiException {
   104	        Reservation reservation = getReservation(id);
   105	
   106	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   107	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only checked-in reservations can check out");
   108	        }
   109	
   110	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   111	
   112	        return createDocument(reservation);
   113	    }
   114	
   115	    public Reservation cancelReservation(long id) throws ApiException {
   116	        Reservation reservation = getReservation(id);
   117	
   118	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
   119	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
   120	            reservation.getStatus() == ReservationStatus.CANCELLED) {
   121	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Reservation cannot be cancelled in this status");
   122	        }
   123	
   124	        PricingStrategy pricingStrategy = PricingStrategyFactory.getStrategy(reservation.getRatePlan());
   125	        BigDecimal refundPercentage = BigDecimal.ZERO;
   126	
   127	        try {
   128	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
   129	            PricingStrategy.PricingResult pricingResult = pricingStrategy.calculatePrice(
   130	                    room, reservation.getCheckIn(), reservation.getCheckOut(),
   131	                    reservation.getNights(), reservation.getCompanyCode());
   132	            refundPercentage = pricingResult.refundPercentage;
   133	        } catch (ApiException e) {
   134	            refundPercentage = BigDecimal.ZERO;
   135	        }
   136	
   137	        BigDecimal refund = MoneyRounder.multiply(
   138	                reservation.getAmountPaid(),
   139	                refundPercentage.divide(BigDecimal.valueOf(100), 2, java.math.RoundingMode.HALF_EVEN)
   140	        );
   141	
   142	        reservation.setStatus(ReservationStatus.CANCELLED);
   143	        reservation.setRefund(refund);
   144	
   145	        return reservation;
   146	    }
   147	
   148	    public ReservationDocument getDocument(long id) throws ApiException {
   149	        Reservation reservation = getReservation(id);
   150	
   151	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
   152	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
   153	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
   154	            throw new ApiException(400, "INVALID_REQUEST", "Document only available for paid reservations");
   155	        }
   156	
   157	        return createDocument(reservation);
   158	    }
   159	
   160	    private void checkRoomAvailability(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws ApiException {
   161	        LocalDate current = checkIn;
   162	        while (current.isBefore(checkOut)) {
   163	            final LocalDate night = current;
   164	            boolean occupied = reservations.stream()
   165	                    .filter(r -> r.getRoomNumber() == roomNumber)
   166	                    .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   167	                    .anyMatch(r -> !night.isBefore(r.getCheckIn()) && night.isBefore(r.getCheckOut()));
   168	
   169	            if (occupied) {
   170	                throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for the selected dates");
   171	            }
   172	
   173	            current = current.plusDays(1);
   174	        }
   175	    }
   176	
   177	    private void sendConfirmationEmail(Reservation reservation) {
   178	        Room room = null;
   179	        try {
   180	            room = roomService.getRoomByNumber(reservation.getRoomNumber());
   181	        } catch (ApiException e) {
   182	            return;
   183	        }
   184	
   185	        ReservationDocument doc = new ReservationDocument(
   186	                reservation.getId(),
   187	                reservation.getGuestName(),
   188	                reservation.getGuestCpf(),
   189	                reservation.getRoomNumber(),
   190	                room.getType(),
   191	                reservation.getCheckIn(),
   192	                reservation.getCheckOut(),
   193	                reservation.getNights(),
   194	                reservation.getSubtotal(),
   195	                reservation.getDiscount(),
   196	                reservation.getTotal()
   197	        );
   198	
   199	        String documentText = formatDocument(doc);
   200	
   201	        String body = "Olá, " + reservation.getGuestName() + "!\n\n" +
   202	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   203	                documentText +
   204	                "\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n" +
   205	                "Até breve!";
   206	
   207	        messageService.sendEmail(
   208	                reservation.getGuestEmail(),
   209	                "Reserva confirmada - Pousada Maré Alta",
   210	                body
   211	        );
   212	    }
   213	
   214	    private ReservationDocument createDocument(Reservation reservation) {
   215	        return new ReservationDocument(
   216	                reservation.getId(),
   217	                reservation.getGuestName(),
   218	                reservation.getGuestCpf(),
   219	                reservation.getRoomNumber(),
   220	                getRoomType(reservation.getRoomNumber()),
   221	                reservation.getCheckIn(),
   222	                reservation.getCheckOut(),
   223	                reservation.getNights(),
   224	                reservation.getSubtotal(),
   225	                reservation.getDiscount(),
   226	                reservation.getTotal()
   227	        );
   228	    }
   229	
   230	    private String formatDocument(ReservationDocument doc) {
   231	        StringBuilder sb = new StringBuilder();
   232	        sb.append("Comprovante de reserva nº ").append(doc.getReservationId()).append("\n");
   233	        sb.append("Hóspede: ").append(doc.getGuestName()).append(" (CPF ").append(formatCpf(doc.getGuestCpf())).append(")\n");
   234	        sb.append("Quarto: ").append(doc.getRoomNumber()).append(" (").append(doc.getRoomType()).append(")\n");
   235	        sb.append("Entrada: ").append(formatDate(doc.getCheckIn())).append(" | ");
   236	        sb.append("Saída: ").append(formatDate(doc.getCheckOut())).append(" | ");
   237	        sb.append(doc.getNights()).append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
   238	        sb.append("Diárias: ").append(formatMoney(doc.getSubtotal())).append("\n");
   239	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   240	            sb.append("Desconto: ").append(formatMoney(doc.getDiscount())).append("\n");
   241	        }
   242	        sb.append("Total: ").append(formatMoney(doc.getTotal()));
   243	        return sb.toString();
   244	    }
   245	
   246	    private String formatDate(LocalDate date) {
   247	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
   248	    }
   249	
   250	    private String formatMoney(BigDecimal value) {
   251	        return String.format("R$ %.2f", value);
   252	    }
   253	
   254	    private String formatCpf(String cpf) {
   255	        if (cpf.length() != 11) return cpf;
   256	        return String.format("%s.%s.%s-%s",
   257	                cpf.substring(0, 3),
   258	                cpf.substring(3, 6),
   259	                cpf.substring(6, 9),
   260	                cpf.substring(9));
   261	    }
   262	
   263	    private String getRoomType(int roomNumber) {
   264	        try {
   265	            return roomService.getRoomByNumber(roomNumber).getType();
   266	        } catch (ApiException e) {
   267	            return "UNKNOWN";
   268	        }
   269	    }
